G = graph([1 2], [2 3]);
G = addedge(G, 1, 3);
disp(G.Edges.EndNodes)
W = addedge(graph([1 2], [2 3], [1 1]), 3, 4, 9);
disp(W.Edges.Weight')

G = graph([1 2], [2 3]);
H = addnode(G, 2);
disp([numnodes(H) numedges(H)])
disp(degree(H)')
N = graph({'a','b'}, {'b','c'});
N = addnode(N, 'z');
disp(N.Nodes.Name')

G = graph([1 1 2], [2 3 3], [4 6 5]);
adjacency(G)
adjacency(G, 'weighted')

G = graph([1 2 3 3], [2 3 1 4]);
c = allcycles(G);
numel(c)
c{1}

G = graph([1 1 2 2 3 4], [2 3 3 4 4 5]);
P = allpaths(G, 1, 5);
fprintf('%d paths\n', numel(P))
for k = 1:numel(P)
  disp(P{k})
end

G = graph([1 2 3 3 4 5], [2 3 1 4 5 6]);
T = bctree(G);
fprintf('%d nodes, %d edges\n', numnodes(T), numedges(T))

D = digraph([1 1 2 3 4], [2 3 4 4 5]);
bfsearch(D, 1)'
bfsearch(D, 1, 'edgetonew')

G = graph([1 2 3 3 4 5], [2 3 1 4 5 6]);
[bins, cut] = biconncomp(G);
